"""
SentinelRAG — Central Security Policy Engine.

Evaluates signals from query inspection, context authorization, and output validation
to produce auditable, explainable security decisions: allow | block | sanitize | review.
"""
from __future__ import annotations

from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, Field

from app.core.logging import get_logger

logger = get_logger(__name__)


class PolicyDecision(str, Enum):
    """Possible decisions generated by the security policy engine."""
    ALLOW = "allow"
    BLOCK = "block"
    SANITIZE = "sanitize"
    REVIEW = "review"
    INCONCLUSIVE = "inconclusive"


class ReasonCode(str, Enum):
    """Standardized reason codes explaining policy actions."""
    NORMAL = "NORMAL"
    PROMPT_INJECTION_DETECTED = "PROMPT_INJECTION_DETECTED"
    SYSTEM_PROMPT_EXTRACTION = "SYSTEM_PROMPT_EXTRACTION"
    CREDENTIAL_LEAKAGE_RISK = "CREDENTIAL_LEAKAGE_RISK"
    DATA_EXFILTRATION_RISK = "DATA_EXFILTRATION_RISK"
    TOOL_MANIPULATION_RISK = "TOOL_MANIPULATION_RISK"
    UNAUTHORIZED_RETRIEVAL_CONTEXT = "UNAUTHORIZED_RETRIEVAL_CONTEXT"
    OUTPUT_CANARY_LEAKAGE = "OUTPUT_CANARY_LEAKAGE"
    OUTPUT_SENSITIVE_DATA_LEAKAGE = "OUTPUT_SENSITIVE_DATA_LEAKAGE"
    OUTPUT_MALICIOUS_SCHEMA = "OUTPUT_MALICIOUS_SCHEMA"
    OUTPUT_UNGROUNDED = "OUTPUT_UNGROUNDED"


class PolicyEvaluationResult(BaseModel):
    """Result of evaluating a security policy rule set."""

    decision: PolicyDecision
    reason_code: ReasonCode
    severity: str  # low | medium | high | critical
    is_allowed: bool
    explanation: str
    metadata: dict[str, Any] = Field(default_factory=dict)


class SecurityPolicyEngine:
    """Evaluates multi-signal threat indicators and renders deterministic policy actions."""

    def evaluate_query_policy(
        self,
        signals: list[dict[str, Any]],
        query_length: int,
        max_query_length: int = 4000,
    ) -> PolicyEvaluationResult:
        """
        Evaluate user query against pre-retrieval security policies.
        Enforces fail-closed blocking on injection, extraction, exfiltration, or tool manipulation.
        """
        if query_length > max_query_length:
            return PolicyEvaluationResult(
                decision=PolicyDecision.BLOCK,
                reason_code=ReasonCode.TOOL_MANIPULATION_RISK,
                severity="medium",
                is_allowed=False,
                explanation=f"Query exceeded maximum allowed length of {max_query_length} characters.",
                metadata={"length": query_length, "limit": max_query_length},
            )

        if not signals:
            return PolicyEvaluationResult(
                decision=PolicyDecision.ALLOW,
                reason_code=ReasonCode.NORMAL,
                severity="low",
                is_allowed=True,
                explanation="Query passed pre-retrieval security inspection.",
            )

        # Categorize primary violation
        has_critical = any(s.get("severity") == "critical" for s in signals)
        has_high = any(s.get("severity") == "high" for s in signals)

        categories = {s.get("category") for s in signals}

        if "direct_prompt_injection" in categories or "system_prompt_override" in categories:
            reason = ReasonCode.PROMPT_INJECTION_DETECTED
            explanation = "Direct prompt injection or system override pattern detected."
        elif "system_prompt_extraction" in categories:
            reason = ReasonCode.SYSTEM_PROMPT_EXTRACTION
            explanation = "System prompt or hidden instruction extraction attempt detected."
        elif "credential_extraction" in categories:
            reason = ReasonCode.CREDENTIAL_LEAKAGE_RISK
            explanation = "Sensitive credential or API key extraction attempt detected."
        elif "data_exfiltration" in categories:
            reason = ReasonCode.DATA_EXFILTRATION_RISK
            explanation = "Potential data exfiltration or external beacon URL detected."
        elif "command_execution" in categories or "tool_manipulation" in categories:
            reason = ReasonCode.TOOL_MANIPULATION_RISK
            explanation = "Command execution or tool manipulation instruction detected."
        else:
            reason = ReasonCode.PROMPT_INJECTION_DETECTED
            explanation = "Suspicious prompt manipulation pattern detected."

        severity = "critical" if has_critical else ("high" if has_high else "medium")

        # In all threat cases, block the query before retrieval or LLM execution
        return PolicyEvaluationResult(
            decision=PolicyDecision.BLOCK,
            reason_code=reason,
            severity=severity,
            is_allowed=False,
            explanation=explanation,
            metadata={"signals_count": len(signals)},
        )

    def evaluate_output_policy(
        self,
        canary_leaked: bool,
        credential_leaked: bool,
        unsafe_schema_detected: bool,
        signals: list[dict[str, Any]],
    ) -> PolicyEvaluationResult:
        """
        Evaluate generated LLM output for leakage and unsafe content.
        Canary disclosure is treated as a critical indirect prompt injection compromise.
        """
        if canary_leaked:
            return PolicyEvaluationResult(
                decision=PolicyDecision.BLOCK,
                reason_code=ReasonCode.OUTPUT_CANARY_LEAKAGE,
                severity="critical",
                is_allowed=False,
                explanation="Model response contained server canary secret; output blocked to prevent data exfiltration.",
                metadata={"canary_leaked": True},
            )

        if credential_leaked:
            return PolicyEvaluationResult(
                decision=PolicyDecision.SANITIZE,
                reason_code=ReasonCode.OUTPUT_SENSITIVE_DATA_LEAKAGE,
                severity="high",
                is_allowed=True,
                explanation="Model response contained sensitive credential patterns; sanitized before returning.",
                metadata={"credential_leaked": True},
            )

        if unsafe_schema_detected:
            return PolicyEvaluationResult(
                decision=PolicyDecision.SANITIZE,
                reason_code=ReasonCode.OUTPUT_MALICIOUS_SCHEMA,
                severity="medium",
                is_allowed=True,
                explanation="Model response contained dangerous URI schemes (e.g. javascript:); sanitized before returning.",
                metadata={"unsafe_schema_detected": True},
            )

        return PolicyEvaluationResult(
            decision=PolicyDecision.ALLOW,
            reason_code=ReasonCode.NORMAL,
            severity="low",
            is_allowed=True,
            explanation="Model output passed security and grounding inspection.",
        )


policy_engine = SecurityPolicyEngine()

